_UNITS = {"s": 1, "m": 60, "h": 3600, "d": 86400}
_UNIT_ORDER = {"d": 3, "h": 2, "m": 1, "s": 0}


def parse_duration(text: str) -> int:
    """Parse a duration string such as ``90s`` or ``1h30m`` into seconds."""
    if not text:
        raise ValueError(f"invalid duration: {text!r}")

    total = 0
    pos = 0
    n = len(text)
    seen = set()
    last_rank = None

    while pos < n:
        if not text[pos].isdigit():
            raise ValueError(f"invalid duration: {text!r}")

        start = pos
        while pos < n and text[pos].isdigit():
            pos += 1

        if pos >= n:
            raise ValueError(f"invalid duration: {text!r}")

        unit = text[pos]
        if unit not in _UNITS:
            raise ValueError(f"invalid duration: {text!r}")

        if unit in seen:
            raise ValueError(f"invalid duration: {text!r}")

        rank = _UNIT_ORDER[unit]
        if last_rank is not None and rank >= last_rank:
            raise ValueError(f"invalid duration: {text!r}")

        total += int(text[start:pos]) * _UNITS[unit]
        seen.add(unit)
        last_rank = rank
        pos += 1

    return total
EOF

